def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2,
        "*": 3, "/": 3,
        "neg": 4,
        ":": 5,
    }
    token_pattern = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[^\s]")

    def integer(text):
        # Chunking also supports literals beyond Python's int-string limit.
        text = text.strip()
        sign = 1
        if text[0] in "+-":
            if text[0] == "-":
                sign = -1
            text = text[1:]
        value = 0
        for i in range(0, len(text), 9):
            chunk = text[i:i + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return sign * value

    def parse(formula):
        nodes = []
        operators = []
        pending_function = None
        need_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append((op, left, right))

        for token in token_pattern.findall(formula):
            if token[0].isdigit():
                nodes.append(("num", integer(token)))
                need_operand = False
            elif token in functions:
                pending_function = token
                need_operand = True
            elif token[0].isalpha():
                nodes.append(("ref", token))
                need_operand = False
            elif token == "(":
                operators.append((pending_function, len(nodes)))
                pending_function = None
                need_operand = True
            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                need_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                function, start = operators.pop()
                if function is not None:
                    arguments = tuple(nodes[start:])
                    del nodes[start:]
                    nodes.append((function, arguments))
                need_operand = False
            elif token == "-" and need_operand:
                operators.append("neg")
            else:
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and precedence[operators[-1]] >= precedence[token]
                ):
                    reduce_operator()
                operators.append(token)
                need_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    trees = {
        name: parse(content[1:])
        if content.startswith("=")
        else ("num", integer(content))
        for name, content in cells.items()
    }

    def expand_arguments(arguments):
        for argument in arguments:
            if argument[0] != ":":
                yield argument
                continue

            first = argument[1][1]
            last = argument[2][1]
            left, right = sorted((ord(first[0]), ord(last[0])))
            top, bottom = sorted((int(first[1:]), int(last[1:])))

            for row in range(top, bottom + 1):
                for column in range(left, right + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("ref", name)

    def calculate(op, left, right):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if op == "=":
            return int(left == right)
        if op == "<>":
            return int(left != right)
        if op == "<":
            return int(left < right)
        if op == "<=":
            return int(left <= right)
        if op == ">":
            return int(left > right)
        return int(left >= right)

    memo = {}
    active = set()

    for root in cells:
        if root in memo:
            continue

        # Explicit stacks avoid recursion limits for formulas and references.
        work = [("cell", root)]
        values = []

        while work:
            task = work.pop()
            action = task[0]

            if action == "cell":
                name = task[1]
                if name not in trees:
                    values.append(0)
                elif name in memo:
                    values.append(memo[name])
                elif name in active:
                    values.append("#CYCLE!")
                else:
                    active.add(name)
                    work.append(("finish_cell", name))
                    work.append(("eval", trees[name]))

            elif action == "finish_cell":
                name = task[1]
                memo[name] = values[-1]
                active.remove(name)

            elif action == "eval":
                node = task[1]
                kind = node[0]

                if kind == "num":
                    values.append(node[1])
                elif kind == "ref":
                    work.append(("cell", node[1]))
                elif kind == "neg":
                    work.append(("negate",))
                    work.append(("eval", node[1]))
                elif kind == "IF":
                    condition, then_branch, else_branch = node[1]
                    work.append(("choose", then_branch, else_branch))
                    work.append(("eval", condition))
                elif kind in ("SUM", "MIN", "MAX"):
                    accumulator = 0 if kind == "SUM" else None
                    work.append((
                        "aggregate_next",
                        kind,
                        expand_arguments(node[1]),
                        accumulator,
                    ))
                else:
                    work.append(("binary_left", kind, node[2]))
                    work.append(("eval", node[1]))

            elif action == "negate":
                if not isinstance(values[-1], str):
                    values[-1] = -values[-1]

            elif action == "binary_left":
                if not isinstance(values[-1], str):
                    left = values.pop()
                    work.append(("binary_right", task[1], left))
                    work.append(("eval", task[2]))

            elif action == "binary_right":
                if not isinstance(values[-1], str):
                    right = values.pop()
                    values.append(calculate(task[1], task[2], right))

            elif action == "choose":
                if not isinstance(values[-1], str):
                    condition = values.pop()
                    branch = task[1] if condition else task[2]
                    work.append(("eval", branch))

            elif action == "aggregate_next":
                _, function, arguments, accumulator = task
                try:
                    argument = next(arguments)
                except StopIteration:
                    values.append(0 if accumulator is None else accumulator)
                else:
                    work.append((
                        "aggregate_value", function, arguments, accumulator
                    ))
                    work.append(("eval", argument))

            elif action == "aggregate_value":
                if not isinstance(values[-1], str):
                    value = values.pop()
                    _, function, arguments, accumulator = task

                    if function == "SUM":
                        accumulator += value
                    elif accumulator is None:
                        accumulator = value
                    elif function == "MIN":
                        accumulator = min(accumulator, value)
                    else:
                        accumulator = max(accumulator, value)

                    work.append((
                        "aggregate_next", function, arguments, accumulator
                    ))

    return {name: memo[name] for name in cells}
